mapper.update:
update auth_password_credentials
set temporary_password_consumed_at = #{consumedAt},
    updated_at = #{consumedAt}
where user_id = #{userId}
  and password_hash = #{expectedPasswordHash}
  and reset_required = TRUE
  and temporary_password_consumed_at is null
  and temporary_password_expires_at > #{consumedAt}

update auth_password_credentials
set password_hash = #{newPasswordHash},
    reset_required = FALSE,
    temporary_password_expires_at = NULL,
    temporary_password_consumed_at = NULL,
    password_changed_at = #{changedAt},
    reset_by = NULL,
    updated_at = #{changedAt}
where user_id = #{userId}
  and password_hash = #{expectedPasswordHash}

update auth_oauth_accounts
set email_at_provider = #{emailAtProvider},
    display_name_at_provider = #{displayNameAtProvider},
    avatar_url_at_provider = #{avatarUrlAtProvider},
    updated_at = #{updatedAt}
where id = #{accountId}
